from pathlib import Path
import cv2,numpy as np,json
P=Path(__file__).parent;Q=P.parent/'phase2';d=json.loads((P/'four-texture-poses.json').read_text());phase=d['player_phase'];f=180/np.tan(np.deg2rad(35));K=np.array([[f,0,320],[0,f,180],[0,0,1]])
def planeH(rec):
 yaw,pitch,h=rec['yaw_pitch_height'];s,c=np.sin(yaw),np.cos(yaw);sp,cp=np.sin(pitch),np.cos(pitch);R=np.array([[c,0,s],[-s*sp,-cp,c*sp],[s*cp,-sp,-c*cp]]);C=np.array([phase[0]-.3*s*cp,h,phase[1]+.3*c*cp]);return K@np.c_[R[:,0],R[:,2],-R@C]
out=[];sift=cv2.SIFT_create(nfeatures=7000)
for i,j in [(0,1),(1,2),(2,3)]:
 a,b=d['frames'][i],d['frames'][j];im1=cv2.imread(str(Q/f'f-{a["frame"]}.png'));im2=cv2.imread(str(Q/f'f-{b["frame"]}.png'));H=planeH(b)@np.linalg.inv(planeH(a));warp=cv2.warpPerspective(im1,H,(640,360));mix=cv2.addWeighted(warp,.5,im2,.5,0);cv2.imwrite(str(P/f'four-plane-warp-{i}-{j}.png'),np.hstack([im2,warp,mix]));k1,q1=sift.detectAndCompute(im1,None);k2,q2=sift.detectAndCompute(im2,None);pairs=cv2.BFMatcher().knnMatch(q1,q2,k=2);m=[x for x,y in pairs if x.distance<.65*y.distance];p1=np.float32([k1[x.queryIdx].pt for x in m]);p2=np.float32([k2[x.trainIdx].pt for x in m]);pred=cv2.perspectiveTransform(p1[:,None,:],H)[:,0,:];err=np.linalg.norm(pred-p2,axis=1);region=(p2[:,0]<250)&(p2[:,1]>190);good=region&(err<2);rec={'frames':[a['frame'],b['frame']],'total_ratio_matches':len(m),'target_leftgrass_matches':int(region.sum()),'predicted_plane_inliers_below2px':int(good.sum()),'inlier_error_median':float(np.median(err[good]))if good.any()else None,'matches':[{'source':p.tolist(),'target':q.tolist(),'predicted':pr.tolist(),'error':float(e),'in_leftgrass_region':bool(r)}for p,q,pr,e,r in zip(p1,p2,pred,err,region)]};out.append(rec);print({k:v for k,v in rec.items()if k!='matches'});draw=cv2.drawMatches(im1,k1,im2,k2,[mm for mm,g in zip(m,good)if g],None,flags=2);cv2.imwrite(str(P/f'four-plane-feature-links-{i}-{j}.jpg'),draw)
(P/'four-plane-correspondence.json').write_text(json.dumps(out,indent=2))
